steps.input:
demos=[([(0,0),(0,11),(1,4),(2,7),(3,1),(3,13),(4,10),(5,6),(5,15)],{(0,0),(0,11),(1,4),(2,7),(5,15)}), ([(0,12),(1,1),(1,4),(2,9),(4,3),(4,7)],{(0,12),(4,3),(4,7)}), ([(0,6),(1,13),(2,2),(3,8),(4,5),(5,0),(5,11)],{(1,13),(3,8),(4,5),(5,0)}), ([(1,5),(2,0),(4,2)],{(1,5),(2,0)}), ([(1,0),(4,3)],{(4,3)})]
for m in range(2,16):
 for a in range(m):
  for b in range(m):
   # any residue class subset can represent selected labels; but avoid classes with contradictory labels
   classes={}
   good=True
   for cells,S in demos:
    for r,c in cells:
     v=(a*r+b*c)%m
     y=(r,c) in S
     if v in classes and classes[v]!=y: good=False; break
     classes[v]=y
    if not good:break
   if good:
    # report complexity of classes and test predicted selection
    print('m,a,b',m,a,b,'classes',classes)
    raise SystemExit
print('none')
